changeSet.sql:
UPDATE repository_to_monitor m SET native_id = ( SELECT min(r.native_id) FROM repository r JOIN identity_provider p ON p.id = r.provider_id JOIN connection c ON c.workspace_id = m.workspace_id AND c.kind = p.type AND c.config->>'serverUrl' = p.server_url AND c.state IN ('ACTIVE','SUSPENDED') WHERE lower(r.name_with_owner) = lower(m.name_with_owner) AND r.native_id > 0 AND EXISTS (SELECT 1 FROM item i WHERE i.workspace_id = m.workspace_id AND i.kind = 'scm.repository' AND i.parent_id IS NULL AND i.source_id = r.id) ) WHERE m.native_id IS NULL;
UPDATE connection c SET config = jsonb_set(c.config, '{gitlabGroupId}', to_jsonb(( SELECT min(o.native_id) FROM organization o JOIN identity_provider p ON p.id = o.provider_id JOIN workspace w ON w.id = c.workspace_id WHERE p.type = c.kind AND p.server_url = c.config->>'serverUrl' AND o.id = w.organization_id AND o.native_id > 0 ))) WHERE c.kind = 'GITLAB' AND c.config->>'gitlabGroupId' IS NULL;
UPDATE connection c SET config = jsonb_set(c.config, '{projectExclusions}', ((c.config->'projectExclusions') - 'unresolvedPaths') || jsonb_build_object('nativeIds', ( SELECT COALESCE(jsonb_agg(DISTINCT native_id), '[]') FROM ( SELECT value::bigint native_id FROM jsonb_array_elements_text( COALESCE(c.config#>'{projectExclusions,nativeIds}', '[]')) UNION SELECT r.native_id FROM repository r JOIN identity_provider p ON p.id = r.provider_id JOIN LATERAL jsonb_array_elements_text( COALESCE(c.config#>'{projectExclusions,unresolvedPaths}', '[]')) path(value) ON lower(r.name_with_owner) = lower(path.value) WHERE p.type = c.kind AND p.server_url = c.config->>'serverUrl' AND r.native_id > 0 AND EXISTS (SELECT 1 FROM item i WHERE i.workspace_id = c.workspace_id AND i.kind = 'scm.repository' AND i.parent_id IS NULL AND i.source_id = r.id) ) ids ))) WHERE c.kind = 'GITLAB' AND jsonb_exists(c.config->'projectExclusions', 'unresolvedPaths');

ALTER TABLE repository_to_monitor ADD CONSTRAINT ck_repository_to_monitor_native_id CHECK (native_id > 0);
ALTER TABLE connection ADD CONSTRAINT ck_connection_gitlab_native_ids CHECK (
    kind <> 'GITLAB' OR (
        jsonb_typeof(config->'gitlabGroupId') = 'number'
        AND (config->>'gitlabGroupId') ~ '^[1-9][0-9]*$'
        AND NOT jsonb_exists(COALESCE(config->'projectExclusions', '{}'), 'unresolvedPaths')
        AND NOT jsonb_path_exists(COALESCE(config#>'{projectExclusions,nativeIds}', '[]'),
            '$[*] ? (@.type() != "number" || @ <= 0)')
    ) IS TRUE
);
